def _find_package_path(root_mod_name, import_name=None):
    # same as before
    try:
        spec = importlib.util.find_spec(root_mod_name)
        if spec is None:
            raise ValueError...
    except ...:
        pass
    else:
        if spec.origin in {"namespace", None}:
            # if import_name provided and import_name != root_mod_name:
            # find spec for import_name
            if import_name and import_name != root_mod_name:
                # get spec for import_name
                package_spec = importlib.util.find_spec(import_name)
                if package_spec and package_spec.submodule_search_locations:
                    # compute common path of its locations
                    package_path = os.path.commonpath(package_spec.submodule_search_locations)
                    # select location from spec.submodule_search_locations where package_path startswith location
                    for location in spec.submodule_search_locations:
                        if package_path.startswith(location):
                            return os.path.dirname(location)
                # fallback: first location
            return os.path.dirname(next(iter(spec.submodule_search_locations)))
        elif spec.submodule_search_locations:
            return os.path.dirname(os.path.dirname(spec.origin))
        else:
            return os.path.dirname(spec.origin)

